// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(c));
        vm.assume(_target != address(0));
        vm.assume(_target != address(this));
        vm.assume(_value > 0);

        vm.deal(address(c), _value);

        uint256 targetBalanceBefore = _target.balance;
        vm.prank(c.owner());
        try c.sendMoney(_target, _value) {
            assertTrue(_target.balance == targetBalanceBefore + _value);
        } catch {
            assertTrue(_target.balance == targetBalanceBefore);
        }
    }
}
